/* ---------- durable infinite drawing notes ---------- */
function noteDb(){
  if(noteDbPromise)return noteDbPromise;
  noteDbPromise=new Promise((res,rej)=>{const r=indexedDB.open(DRAW_DB,DRAW_DB_VERSION);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('pages')){const st=db.createObjectStore('pages',{keyPath:'key'});st.createIndex('courseDate',['courseKey','dateKey'],{unique:false});st.createIndex('dirty','dirty',{unique:false})}if(!db.objectStoreNames.contains('revisions')){const st=db.createObjectStore('revisions',{keyPath:'id'});st.createIndex('pageKey','pageKey',{unique:false});st.createIndex('at','at',{unique:false})}if(!db.objectStoreNames.contains('assets')){const st=db.createObjectStore('assets',{keyPath:'id'});st.createIndex('dirty','dirty',{unique:false});st.createIndex('createdAt','createdAt',{unique:false})}};r.onsuccess=()=>{const db=r.result;db.onversionchange=()=>{db.close();noteDbPromise=null};res(db)};r.onerror=()=>{noteDbPromise=null;rej(r.error)}});return noteDbPromise
}
async function noteGet(store,key){const db=await noteDb();return new Promise((res,rej)=>{const r=db.transaction(store,'readonly').objectStore(store).get(key);r.onsuccess=()=>res(r.result||null);r.onerror=()=>rej(r.error)})}
async function notePut(store,value){const db=await noteDb();return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>res(value);tx.onerror=()=>rej(tx.error)})}
async function noteDelete(store,key){const db=await noteDb();return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function noteAll(store='pages'){const db=await noteDb();return new Promise((res,rej)=>{const r=db.transaction(store,'readonly').objectStore(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
async function noteAllIndex(store,indexName,key){const db=await noteDb();return new Promise((res,rej)=>{const st=db.transaction(store,'readonly').objectStore(store),idx=st.index(indexName),r=idx.getAll(IDBKeyRange.only(key));r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
function pageKey(course,date,pageId){return `${course}::${date}::${pageId}`}
function makePage(course=drawCourse,date=drawDate,index=0,{dirty=false}={}){const id=`p${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`;return{schema:3,key:pageKey(course,date,id),courseKey:course,dateKey:date,pageId:id,order:index,paper:'ruled',width:CANVAS_W,height:CANVAS_H,strokes:[],images:[],attachments:[],rev:0,cloudRev:0,dirty:!!dirty,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}}
async function pagesFor(course,date){return (await noteAllIndex('pages','courseDate',[course,date])).sort((a,b)=>(Number(a.order)||0)-(Number(b.order)||0)||String(a.createdAt).localeCompare(String(b.createdAt)))}
function pageHasContent(p){return !!((p?.strokes||[]).length||(p?.images||[]).length||(p?.attachments||[]).length||Number(p?._strokeCount)>0||Number(p?._itemCount)>0||Number(p?.rev)>0||p?.conflictCopy)}
function compactPageMemory(p){if(!p)return p;const n=(p.strokes||[]).length,m=(p.images||[]).length+(p.attachments||[]).length;return{...p,strokes:[],images:p.images||[],attachments:p.attachments||[],_unloaded:true,_strokeCount:n,_itemCount:m}}
async function ensurePages(){
  let full=await pagesFor(drawCourse,drawDate);
  if(!full.length){const p=makePage(drawCourse,drawDate,0,{dirty:false});await notePut('pages',p);full=[p]}
  activePageIndex=Math.max(0,Math.min(activePageIndex,full.length-1));activePage=structuredClone(full[activePageIndex]);
  drawPages=full.map((p,i)=>i===activePageIndex?structuredClone(p):compactPageMemory(p));
  activePageChanged=false;undoStack=[];redoStack=[];
  renderInfiniteNotebook();
}
function noteStatus(text,kind=''){const el=$('#drawingSaveState');if(el){el.textContent=text;el.className=`save-state ${kind}`.trim()}}
function canvasPoint(e,c){const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height,p:Number(e.pressure)||.5}}
function renderPaper(ctx,style){ctx.save();ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.fillStyle='#faf9f4';ctx.fillRect(0,0,CANVAS_W,CANVAS_H);ctx.strokeStyle='#dfe4e9';ctx.lineWidth=1;if(style==='ruled'){for(let y=120;y<CANVAS_H;y+=54){ctx.beginPath();ctx.moveTo(80,y);ctx.lineTo(CANVAS_W-60,y);ctx.stroke()}ctx.strokeStyle='#efc7c7';ctx.beginPath();ctx.moveTo(125,0);ctx.lineTo(125,CANVAS_H);ctx.stroke()}else if(style==='grid'){for(let x=0;x<CANVAS_W;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,CANVAS_H);ctx.stroke()}for(let y=0;y<CANVAS_H;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(CANVAS_W,y);ctx.stroke()}}ctx.restore()}
function drawStroke(ctx,s){const pts=s.points||[];if(!pts.length)return;ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=s.color||'#11151d';ctx.globalAlpha=s.tool==='highlighter'?.26:s.tool==='pencil'?.72:1;ctx.globalCompositeOperation='source-over';ctx.lineWidth=(Number(s.width)||4)*(s.tool==='highlighter'?3:s.tool==='pencil'?.82:1);ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++){const a=pts[i-1],b=pts[i],pressure=((a.p||.5)+(b.p||.5))/2;ctx.lineWidth=(Number(s.width)||4)*(s.tool==='highlighter'?3:s.tool==='pencil'?.82:1)*(s.tool==='highlighter'?1:Math.max(.7,Math.min(1.35,.65+pressure*.7)));ctx.lineTo(b.x,b.y)}if(pts.length===1)ctx.lineTo(pts[0].x+.01,pts[0].y+.01);ctx.stroke();ctx.restore()}
function cacheAssetBitmap(id,bitmap){if(assetBitmapCache.has(id)){const old=assetBitmapCache.get(id);if(old!==bitmap&&old?.close)try{old.close()}catch(_){}const oi=assetBitmapOrder.indexOf(id);if(oi>=0)assetBitmapOrder.splice(oi,1)}assetBitmapCache.set(id,bitmap);assetBitmapOrder.push(id);while(assetBitmapOrder.length>14){const drop=assetBitmapOrder.shift(),old=assetBitmapCache.get(drop);assetBitmapCache.delete(drop);if(old?.close)try{old.close()}catch(_){}}}
async function assetRenderable(id){if(!id)return null;if(assetBitmapCache.has(id))return assetBitmapCache.get(id);if(assetLoadPending.has(id))return null;assetLoadPending.add(id);try{const a=await noteGet('assets',id);if(!a?.blob)return null;let bmp=null;if('createImageBitmap'in window){try{bmp=await createImageBitmap(a.blob)}catch(_){}}if(!bmp){bmp=await new Promise((res,rej)=>{const img=new Image(),url=URL.createObjectURL(a.blob);img.onload=()=>{URL.revokeObjectURL(url);res(img)};img.onerror=()=>{URL.revokeObjectURL(url);rej(new Error('Image decode failed'))};img.src=url})}cacheAssetBitmap(id,bmp);return bmp}finally{assetLoadPending.delete(id)}}
