function drawAttachmentCard(ctx,it){const x=Number(it.x)||120,y=Number(it.y)||120,w=Math.max(240,Number(it.w)||620),h=Math.max(120,Number(it.h)||170);ctx.save();ctx.fillStyle='#ffffff';ctx.strokeStyle='#d6d9df';ctx.lineWidth=3;ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,w,h,24);else ctx.rect(x,y,w,h);ctx.fill();ctx.stroke();ctx.fillStyle='#272b34';ctx.font='700 48px system-ui';ctx.fillText(it.type==='application/pdf'?'PDF':'FILE',x+34,y+68);ctx.fillStyle='#575d69';ctx.font='34px system-ui';const name=String(it.name||'Attachment');ctx.fillText(name.length>30?name.slice(0,29)+'…':name,x+34,y+122);ctx.restore()}
