function pageUndoState(){return{strokes:structuredClone(activePage?.strokes||[]),images:structuredClone(activePage?.images||[]),attachments:structuredClone(activePage?.attachments||[])}}
function applyUndoState(v){if(!activePage)return;activePage.strokes=structuredClone(v?.strokes||Array.isArray(v)?v:[]);activePage.images=structuredClone(v?.images||[]);activePage.attachments=structuredClone(v?.attachments||[])}
