async function switchDrawContext(course,date){if(activePageChanged)await saveActiveDrawing({checkpoint:true});drawCourse=course||'general';drawDate=date||localDateKey(new Date());activePageIndex=0;await ensurePages();loadNoteText();await renderDayChips();renderNotebookContext();noteStatus(drawPages.some(p=>p.dirty)?'Saved locally · cloud pending':'Local + OneDrive backup',drawPages.some(p=>p.dirty)?'dirty':'');const vp=$('#drawingViewport');if(vp)vp.scrollTop=0}
function renderNotebookContext(){const opt=[...$('#notesCourse').options].find(o=>o.value===drawCourse),name=opt?.textContent||drawCourse;$('#notebookContext').textContent=`${name} · ${fmtDate(`${drawDate}T12:00:00`,{weekday:'short',month:'short',day:'numeric'})}`}
