function defaultInsertRect(asset,ordinal=0){const maxW=CANVAS_W*.72,maxH=CANVAS_H*.56,iw=Number(asset.width)||900,ih=Number(asset.height)||650,scale=Math.min(1,maxW/iw,maxH/ih),w=Math.max(260,iw*scale),h=Math.max(180,ih*scale);return{x:Math.max(60,(CANVAS_W-w)/2+ordinal*28),y:180+ordinal*34,w,h}}
function updateItemTools(){const del=$('#deleteItemBtn'),fit=$('#fitItemBtn'),open=$('#openItemBtn');if(del)del.disabled=!selectedItemId;if(fit)fit.disabled=!selectedItemId;if(open)open.disabled=!selectedItemId}
async function insertFiles(files,{source='picker'}={}){const arr=[...files].filter(Boolean);if(!arr.length)return;activateVisibleSegment();if(!activePage)return;pushUndo();let ordinal=0;for(const f of arr){const asset=await createAssetFromFile(f,{source}),r=defaultInsertRect(asset,ordinal++),z=Date.now()+ordinal;if(asset.type.startsWith('image/')){activePage.images=activePage.images||[];const it={id:`i${asset.id}`,assetId:asset.id,name:asset.name,type:asset.type,...r,rotation:0,opacity:1,z};activePage.images.push(it);selectedItemId=it.id;assetRenderable(asset.id).then(()=>{const c=activeCanvas();if(c)drawPageToCanvas(activePage,c)}).catch(()=>{})}else{activePage.attachments=activePage.attachments||[];const it={id:`f${asset.id}`,assetId:asset.id,name:asset.name,type:asset.type,x:120,y:190+ordinal*34,w:CANVAS_W-240,h:170,z};activePage.attachments.push(it);selectedItemId=it.id}}activePageChanged=true;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c);updateItemTools();await saveActiveDrawing({checkpoint:true,cloud:false});noteStatus(`${arr.length} item${arr.length===1?'':'s'} saved locally · cloud pending`,'dirty');scheduleNoteCloud(900);closeInsertSheet()}
function openInsertSheet(){const s=$('#insertSheet');if(s){s.hidden=false;requestAnimationFrame(()=>s.classList.add('open'))}}
function closeInsertSheet(){const s=$('#insertSheet');if(!s)return;s.classList.remove('open');setTimeout(()=>{if(!s.classList.contains('open'))s.hidden=true},180)}
async function pasteFromClipboard(){try{if(!navigator.clipboard?.read)throw new Error('Clipboard image paste is not supported here');const items=await navigator.clipboard.read(),files=[];for(const item of items){for(const type of item.types||[]){if(type.startsWith('image/')){const b=await item.getType(type);files.push(new File([b],`pasted-${Date.now()}.${safeAssetExt(type)}`,{type}));break}}}if(!files.length)throw new Error('No image found in clipboard');await insertFiles(files,{source:'clipboard'})}catch(e){noteStatus(`${String(e.message||e)} · use Photos`, 'error')}}
function notebookItemAt(p){if(!activePage)return null;const items=pageItems(activePage).slice().reverse();for(const it of items){const x=Number(it.x)||0,y=Number(it.y)||0,w=Number(it.w)||0,h=Number(it.h)||0;if(p.x>=x&&p.x<=x+w&&p.y>=y&&p.y<=y+h)return it}return null}
function findActiveItem(id=selectedItemId){if(!activePage||!id)return null;return (activePage.images||[]).find(x=>x.id===id)||(activePage.attachments||[]).find(x=>x.id===id)||null}
