async function endItemGesture(){if(!itemGesture)return;itemGesture=null;if(activePageChanged)await saveActiveDrawing({checkpoint:false})}
async function deleteSelectedItem(){if(!activePage||!selectedItemId)return;pushUndo();const id=selectedItemId;activePage.images=(activePage.images||[]).filter(x=>x.id!==id);activePage.attachments=(activePage.attachments||[]).filter(x=>x.id!==id);selectedItemId='';activePageChanged=true;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c);updateItemTools();await saveActiveDrawing({checkpoint:true})}
