  if(!activePage||!activePageChanged)return;const draft={...structuredClone(activePage),dirty:true,updatedAt:new Date().toISOString()};notePut('pages',draft).catch(e=>log('note-emergency-save-error',{error:String(e)}));lastStrokeSafetySaveAt=Date.now();
