async function restoreCloudNotes(){noteStatus('Checking OneDrive note revisions…','dirty');await flushDrawingCloud().catch(()=>{});const files=await listCloudNoteFiles(),latest=new Map();for(const f of files){const m=String(f.name).match(/^whn2\.([^.]+)\.(\d{4}-\d{2}-\d{2})\.([^.]+)\.r(\d+)\.(\d+)\.json$/);if(!m)continue;const k=`${m[1]}|${m[2]}|${m[3]}`,rev=Number(m[4])||0,stamp=Number(m[5])||0,prev=latest.get(k);if(!prev||rev>prev.rev||(rev===prev.rev&&stamp>prev.stamp))latest.set(k,{rev,stamp,file:f})}let imported=0,conflicts=0;for(const {file} of latest.values()){const snap=await fetchGraphDownload(file.id),rp=snap?.page;if(!rp?.key||!Array.isArray(rp.strokes))continue;await ensurePageAssetsLocal(rp);const lp=await noteGet('pages',rp.key);if(!lp){rp.dirty=false;rp.cloudRev=rp.rev;await notePut('pages',rp);imported++;continue}const remoteNew=(Number(rp.rev)||0)>(Number(lp.cloudRev)||0)||Date.parse(rp.updatedAt||0)>Date.parse(lp.updatedAt||0);if(!remoteNew)continue;if(lp.dirty&&JSON.stringify({s:lp.strokes||[],i:lp.images||[],a:lp.attachments||[]})!==JSON.stringify({s:rp.strokes||[],i:rp.images||[],a:rp.attachments||[]})){const cp=structuredClone(rp),newId=`${rp.pageId}c${Date.now().toString(36).slice(-4)}`;cp.pageId=newId;cp.key=pageKey(cp.courseKey,cp.dateKey,newId);cp.order=(Number(lp.order)||0)+.5;cp.dirty=false;cp.cloudRev=cp.rev;cp.conflictCopy=true;await notePut('pages',cp);conflicts++}else{rp.dirty=false;rp.cloudRev=rp.rev;await notePut('pages',rp);imported++}}await switchDrawContext(drawCourse,drawDate);$('#noteSafetyStatus').textContent=`OneDrive restore complete · ${imported} updated · ${conflicts} conflict copies preserved`;noteStatus('Local + OneDrive backup');return{imported,conflicts}}
