const AUTH_DB='warrior-mobile-auth-v01';
function authDb(){return new Promise((res,rej)=>{const r=indexedDB.open(AUTH_DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('kv'))r.result.createObjectStore('kv')};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
