async function login(){cfg=loadJson(CFG_KEY,cfg);if(!cfg.clientId){cfg={...cfg,clientId:DEFAULT_MS_CLIENT_ID};saveJson(CFG_KEY,cfg)}if(!cfg.clientId){setView('setup');renderStatus({kind:'error',text:'Enter Microsoft client ID first'});return}const verifier=rand(64),challenge=b64url(await sha256(verifier)),stateId=rand(24);sessionStorage.setItem('pkceVerifier',verifier);sessionStorage.setItem('oauthState',stateId);const u=new URL(`https://login.microsoftonline.com/${encodeURIComponent(cfg.tenant||'common')}/oauth2/v2.0/authorize`);u.search=new URLSearchParams({client_id:cfg.clientId,response_type:'code',redirect_uri:redirectUri(),response_mode:'query',scope:AUTH_SCOPES,state:stateId,code_challenge:challenge,code_challenge_method:'S256',prompt:'select_account'}).toString();location.href=u.toString()}
