async function fetchCloudSnapshots(){const out=[];const legacy=await fetchJsonContent(legacyGraphFilePath(),{quiet:true});if(legacy)out.push(legacy);out.push(...await listDeviceSnapshots());const seen=new Set(),dedup=[];for(const x of out){const k=`${x.deviceId||''}|${Number(x.updatedAt||0)}|${JSON.stringify(x.clocks||{}).length}|${JSON.stringify(x.warriorState||{}).length}`;if(seen.has(k))continue;seen.add(k);dedup.push(x)}dedup.sort((a,b)=>Number(a.updatedAt||0)-Number(b.updatedAt||0));return dedup}
async function writeDeviceCloud(payload){await ensureSyncDeviceFolder();const r=await graph(deviceGraphFilePath(),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error(`OneDrive device write failed (${r.status})`);return r.json().catch(()=>null)}
async function syncNow(){cfg=loadJson(CFG_KEY,cfg);$('#syncNowBtn').disabled=true;renderStatus({text:'OneDrive: conflict-safe syncing…'});try{const snapshots=await fetchCloudSnapshots(),local=state||{};let merged=local,clocks={...(meta.clocks||{})};for(const remote of snapshots){const res=merge(merged,remote.warriorState||{},clocks,remote.clocks||{},remote.updatedAt||0);merged=res.state;clocks=res.clocks}state=merged;meta.clocks=clocks;const own=snapshots.find(x=>String(x.deviceId||'')===String(meta.deviceId||''));const changed=!own||JSON.stringify(state)!==JSON.stringify(own.warriorState||{})||JSON.stringify(meta.clocks)!==JSON.stringify(own.clocks||{});let payload=own||null;if(changed){payload={schema:SCHEMA,app:'Warrior Hub',syncMode:'device-shard-v1',version:`mobile-${APP_VERSION}`,updatedAt:Date.now(),deviceId:meta.deviceId,clocks:meta.clocks,warriorState:state};await writeDeviceCloud(payload)}if(!payload)payload={schema:SCHEMA,app:'Warrior Hub',version:`mobile-${APP_VERSION}`,updatedAt:Date.now(),deviceId:meta.deviceId,clocks:meta.clocks,warriorState:state};cloud=payload;meta.lastSyncAt=Date.now();meta.shardedSync=true;saveLocalCloud();renderAll();renderStatus({kind:'ok',text:`OneDrive conflict-safe sync · ${state.assignments?.length||0} assignments`});flushDrawingCloud().catch(e=>log('drawing-backup-after-sync',{error:String(e)}));log('sync-success',{changed,updatedAt:payload.updatedAt,snapshotCount:snapshots.length,deviceFile:deviceFileName()})}catch(e){log('sync-error',{error:String(e.message||e)});renderStatus({kind:'error',text:String(e.message||e)})}finally{$('#syncNowBtn').disabled=false}}
function schedulePush(ms=1000){clearTimeout(pushTimer);pushTimer=setTimeout(syncNow,ms)}

/* ---------- v0.6 live desktop Study + Spotify remote ---------- */
function remoteFilePath(name){return `/me/drive/root:/${graphPath([...rootFolderParts(),name])}:/content`}
function remoteFolderPath(name){return `/me/drive/root:/${graphPath([...rootFolderParts(),name])}`}
function remoteIsFresh(){return !!remoteLive&&Date.now()-Number(remoteLive.at||0)<REMOTE_STALE_MS}
function remoteRemaining(){const s=remoteLive?.study||{};if(s.running&&s.endAt)return Math.max(0,Number(s.endAt)-Date.now());return Math.max(0,Number(s.remainingMs)||0)}
function remoteTime(ms){const total=Math.max(0,Math.ceil(Number(ms||0)/1000)),m=Math.floor(total/60),s=total%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function remotePosition(){const p=remoteLive?.spotify||{},base=Math.max(0,Number(p.position)||0),dur=Math.max(0,Number(p.duration)||0),stamp=Number(p.at)||Date.now();const est=base+(p.playing&&p.progressConfirmed?Math.max(0,Date.now()-stamp)/1000:0);return dur?Math.min(dur,est):est}
async function fetchRemoteLive({quiet=true}={}){if(remoteFetchBusy)return remoteLive;remoteFetchBusy=true;try{const r=await graph(remoteFilePath(REMOTE_LIVE_FILE),{cache:'no-store'});if(r.status===404){remoteLive=null;remoteLastError='Desktop bridge has not published yet';return null}if(!r.ok)throw new Error(`Desktop bridge read failed (${r.status})`);const j=await r.json();remoteLive=j?.type==='warrior-mobile-live'?j:null;remoteLastError='';if(currentView==='study')renderRemoteStudy();if(currentView==='today')renderTimer();return remoteLive}catch(e){remoteLastError=String(e.message||e);if(!quiet)renderStatus({kind:'error',text:remoteLastError});return null}finally{remoteFetchBusy=false}}
async function ensureRemoteCommandFolder(){const target=remoteFolderPath(REMOTE_COMMAND_DIR),parent=`/me/drive/root:/${graphPath(rootFolderParts())}:/children`;let r=await graph(target);if(r.ok)return;if(r.status!==404)throw new Error(`Remote command folder check failed (${r.status})`);r=await graph(parent,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:REMOTE_COMMAND_DIR,folder:{},'@microsoft.graph.conflictBehavior':'fail'})});if(!r.ok&&r.status!==409)throw new Error(`Could not create remote command folder (${r.status})`)}
async function sendRemoteCommand(action,payload={}){if(remoteCommandBusy&&/^study\./.test(action))return false;const token=await accessToken();if(!token){setView('setup');renderStatus({kind:'error',text:'Sign in with Microsoft to control the desktop'});return false}if(/^study\./.test(action))remoteCommandBusy=true;try{await ensureRemoteCommandFolder();const seq=`${Date.now()}-${Math.random().toString(36).slice(2,9)}`,name=`cmd-${String(Date.now()).padStart(13,'0')}-${seq.slice(-7)}.json`;const cmd={schema:1,type:'warrior-mobile-command',seq,at:Date.now(),deviceId:meta.deviceId,action,payload};const path=`/me/drive/root:/${graphPath([...rootFolderParts(),REMOTE_COMMAND_DIR,name])}:/content`;const r=await graph(path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(cmd)});if(!r.ok)throw new Error(`Remote command failed (${r.status})`);setTimeout(()=>fetchRemoteLive().catch(()=>{}),500);return true}catch(e){remoteLastError=String(e.message||e);renderRemoteStudy();return false}finally{remoteCommandBusy=false}}
function spotifyUiTime(sec){const s=Math.max(0,Math.floor(Number(sec)||0)),m=Math.floor(s/60);return `${m}:${String(s%60).padStart(2,'0')}`}
function renderRemoteStudy(){const online=remoteIsFresh(),s=remoteLive?.study||{},p=remoteLive?.spotify||{},phase=s.phase==='break'?'BREAK':'FOCUS',remaining=remoteRemaining();const status=$('#remoteDesktopStatus');if(status){status.textContent=online?'Desktop connected':(remoteLastError||'Waiting for desktop…');status.className=`remote-status ${online?'online':'offline'}`}const phaseEl=$('#remotePhase');if(phaseEl)phaseEl.textContent=phase;const timeEl=$('#remoteTimerText');if(timeEl)timeEl.textContent=online?remoteTime(remaining):'--:--';const cycle=$('#remoteCycle');if(cycle)cycle.textContent=online?`Cycle ${Math.max(0,Number(s.cycles)||0)+1} · ${s.autoAdvance===false?'manual next':'auto advance'}`:'Open Warrior Hub on your PC and keep OneDrive connected.';const toggle=$('#remoteTimerToggle');if(toggle){toggle.textContent=s.running?'Pause':'Start';toggle.disabled=!online}const skip=$('#remoteTimerSkip'),reset=$('#remoteTimerReset');if(skip)skip.disabled=!online;if(reset)reset.disabled=!online;const art=$('#remoteSpotifyArt');if(art)art.innerHTML=p.artwork?`<img src="${esc(p.artwork)}" alt="">`:'♫';const title=$('#remoteSpotifyTitle');if(title)title.textContent=p.title||'Spotify on desktop';const artist=$('#remoteSpotifyArtist');if(artist)artist.textContent=p.artist||(online?'Waiting for track metadata…':'Desktop offline');const dur=Math.max(0,Number(p.duration)||0),pos=remotePosition(),pct=dur?Math.max(0,Math.min(100,pos/dur*100)):0,fill=$('#remoteSpotifyProgressFill');if(fill)fill.style.width=`${pct}%`;const t=$('#remoteSpotifyTime');if(t)t.textContent=dur?`${spotifyUiTime(pos)} · −${spotifyUiTime(Math.max(0,dur-pos))}`:'';const play=$('#remoteSpotifyToggle');if(play){play.textContent=p.playing?'Ⅱ':'▶';play.disabled=!online}const prev=$('#remoteSpotifyPrev'),next=$('#remoteSpotifyNext'),shuffle=$('#remoteSpotifyShuffle');if(prev)prev.disabled=!online;if(next)next.disabled=!online;if(shuffle){shuffle.disabled=!online;shuffle.classList.toggle('active',!!p.shuffleOn);shuffle.textContent=p.shuffleOn?'Shuffle On':'Shuffle'}document.body.classList.toggle('remote-break',online&&s.phase==='break')}
function startRemotePolling(){clearInterval(remotePollTimer);remotePollTimer=setInterval(()=>{if(document.visibilityState==='visible')fetchRemoteLive().catch(()=>{})},REMOTE_POLL_MS);fetchRemoteLive().catch(()=>{})}
function vapidKeyBytes(s){let b=String(s).replace(/-/g,'+').replace(/_/g,'/');while(b.length%4)b+='=';const raw=atob(b),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
async function pushSubscription(){if(!('serviceWorker'in navigator)||!('PushManager'in window))return null;const reg=await navigator.serviceWorker.ready;return reg.pushManager.getSubscription()}
async function savePushSubscription(sub){if(!sub)return false;const token=await accessToken();if(!token)throw new Error('Sign in with Microsoft first');const body={schema:1,type:'warrior-mobile-push',appVersion:APP_VERSION,deviceId:meta.deviceId,at:Date.now(),subscription:sub.toJSON()};const r=await graph(remoteFilePath(REMOTE_PUSH_FILE),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error(`Phone alert registration failed (${r.status})`);return true}
async function enablePhoneAlerts(){const status=$('#phoneAlertsStatus'),btn=$('#enablePhoneAlertsBtn');if(btn)btn.disabled=true;try{if(!window.isSecureContext||!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw new Error('Web Push is not available here. Open the installed Home Screen app.');if(Notification.permission!=='granted'){const p=await Notification.requestPermission();if(p!=='granted')throw new Error('Notifications were not allowed')}const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidKeyBytes(MOBILE_VAPID_PUBLIC_KEY)});await savePushSubscription(sub);if(status)status.textContent='Phone alerts ON · Focus/Break can notify while the app is closed';if(btn)btn.textContent='Refresh phone alerts'}catch(e){if(status)status.textContent=String(e.message||e)}finally{if(btn)btn.disabled=false}}
async function refreshPhoneAlertStatus(){const status=$('#phoneAlertsStatus'),btn=$('#enablePhoneAlertsBtn');if(!status||!btn)return;if(!('PushManager'in window)||!('Notification'in window)){status.textContent='Push alerts unsupported here';btn.disabled=true;return}const sub=await pushSubscription().catch(()=>null);if(Notification.permission==='granted'&&sub){status.textContent='Phone alerts ON';btn.textContent='Refresh phone alerts';if(await accessToken())savePushSubscription(sub).catch(()=>{})}else{status.textContent=Notification.permission==='denied'?'Notifications are blocked in iOS settings':'Enable once for Focus/Break alerts while closed';btn.textContent='Enable phone alerts'}}


