  $$('.tab').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('#syncNowBtn').addEventListener('click',syncNow);$('#assignmentFilter').addEventListener('change',renderAssignments);$('#assignmentSearch').addEventListener('input',renderAssignments);$('#calPrev').addEventListener('click',()=>{calCursor=new Date(calCursor.getFullYear(),calCursor.getMonth()-1,1);renderCalendar()});$('#calNext').addEventListener('click',()=>{calCursor=new Date(calCursor.getFullYear(),calCursor.getMonth()+1,1);renderCalendar()});$('#calendarGrid').addEventListener('click',e=>{const b=e.target.closest('[data-date]');if(b){calSelected=b.dataset.date;renderCalendar()}});$('#dayTabs').addEventListener('click',e=>{const b=e.target.closest('[data-day]');if(b){selectedDay=b.dataset.day;renderSchedule()}});
